        with open(REGISTRY_PATH, "r") as handle:
            data = json.load(handle)
        if isinstance(data, dict):
            if isinstance(data.get("subnets"), list):
                return data["subnets"]
            return list(data.values())
    except Exception:
        pass
    return []


def _registry_netuids() -> List[int]:
